type UserPreferences = {
  theme: string
  language: string
  emailNotifications: boolean
  timezone: string
}

async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) {
      throw new Error(`Failed to fetch user preferences: ${res.status}`)
    }
    return res.json()
  } catch {
    return {
      theme: 'light',
      language: 'en',
      emailNotifications: true,
      timezone: 'UTC',
    }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <dl>
        <dt>Theme</dt>
        <dd>{preferences.theme}</dd>
        <dt>Language</dt>
        <dd>{preferences.language}</dd>
        <dt>Email notifications</dt>
        <dd>{preferences.emailNotifications ? 'On' : 'Off'}</dd>
        <dt>Timezone</dt>
        <dd>{preferences.timezone}</dd>
      </dl>
    </div>
  )
}

